import java.util.HashSet;
import java.util.Set;

public class BruteForceDistinct {
    public long countDistinct(String s) {
        int n = s.length();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                seen.add(s.substring(i, j));
            }
        }
        return seen.size();
    }

    public static void main(String[] args) {
        System.out.println(new BruteForceDistinct().countDistinct("abab"));
    }
}

